static int
pcap_not_initialized(pcap_t *pcap)
{
        if (pcap->activated) {
                /* A module probably forgot to set the function pointer */
                (void)pcap_snprintf(pcap->errbuf, sizeof(pcap->errbuf),
                    "This operation isn't properly handled by that device");
                return (PCAP_ERROR);
